var n=`1226-moros-y-cristianos`;var t=`world-1226`;var a=`CU`;var s=`central-america-caribbean`;var r=4;var o=548;var l={en:`Moros y Cristianos`,ua:`Морос і крістіанос`};var d={en:`Moros y Cristianos is a dish from Cuba featuring black beans, yellow onion, green bell pepper, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Морос і крістіанос, страва кухні країни Куба з такими основними складниками: чорна квасоля, жовта цибуля, зелений солодкий перець, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var c=[{en:`Soak the dried beans in ample clean cold water for about 420 minutes, drain and discard the soaking water; cook fully in fresh water.`,ua:`Замочіть сухі бобові у достатній кількості чистої холодної води на приблизно 420 хвилин, злийте її й повністю зваріть у свіжій воді.`,t:[`soaking-legumes`],m:420,i:[[`black-beans`,370,`g`],[`water`,950,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 90 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 90 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:90,i:[[`water`,1050,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`green-bell-pepper`,140,`g`],[`garlic`,4,`clove`],[`olive-oil`,40,`ml`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 25 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 25 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`white-rice`,410,`g`],[`water`,530,`ml`],[`ground-cumin`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime-juice`,25,`ml`]]}];var g={slug:n,id:t,country:`CU`,region:s,servings:4,minutes:548,title:l,text:d,steps:c};export{a as country,g as default,t as id,o as minutes,s as region,r as servings,n as slug,c as steps,d as text,l as title};